// Actual original HEADS context, legitimate StemsRetriever.process and CLinker
// StemBuilder; selected independent glyph parts/pixel filters, not automatic parity.
import org.audiveris.omr.sheet.Book;import java.util.*;import java.nio.file.*;import java.lang.reflect.*;import java.awt.geom.*;
public class StemCacheSigLifecycleProbe extends GridFinalProbe {
 private final Object book;public StemCacheSigLifecycleProbe(Book b,SortedSet<Integer> ids){super(b,ids);book=b;}
 static Object en(String c,String n)throws Exception{return Class.forName("org.audiveris.omr."+c).getField(n).get(null);}
 static void set(Object o,String n,Object v)throws Exception{for(Class<?> c=o.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(n);f.setAccessible(true);f.set(o,v);return;}catch(NoSuchFieldException e){}throw new NoSuchFieldException(n);}
 static Object table(byte[] pixels,int w,int h,String orientation)throws Exception {Object bp=Class.forName("ij.process.ByteProcessor").getConstructor(int.class,int.class,byte[].class).newInstance(w,h,pixels);Object f=Class.forName("org.audiveris.omr.run.RunTableFactory").getConstructor(Class.forName("org.audiveris.omr.run.Orientation")).newInstance(en("run.Orientation",orientation));return f.getClass().getMethod("createTable",Class.forName("ij.process.ByteProcessor")).invoke(f,bp);}
 static Object glyph(int x,int y,int w,int h,String orientation)throws Exception{return Class.forName("org.audiveris.omr.glyph.Glyph").getConstructor(int.class,int.class,Class.forName("org.audiveris.omr.run.RunTable")).newInstance(x,y,table(new byte[w*h],w,h,orientation));}
 static String physical(Object g)throws Exception {Object t=call(g,"getRunTable");List<String> runs=new ArrayList<>();for(int i=0;i<(Integer)call(t,"getSize");i++){Iterator<?> it=(Iterator<?>)call(t,"iterator",i);while(it.hasNext()){Object r=it.next();runs.add("["+i+","+call(r,"getStart")+","+call(r,"getLength")+"]");}}return "{\"bounds\":"+rect(call(g,"getBounds"))+",\"orientation\":\""+call(t,"getOrientation")+"\",\"runs\":["+String.join(",",runs)+"]}";}
 static String impacts(Object p)throws Exception {if(p==null)return "null";List<String> vals=new ArrayList<>();for(int i=0;i<(Integer)call(p,"getImpactCount");i++)vals.add("{\"name\":\""+call(p,"getName",i)+"\",\"weight\":"+call(p,"getWeight",i)+",\"impact\":"+call(p,"getImpact",i)+"}");return "{\"grade\":"+call(p,"getGrade")+",\"intrinsic_ratio\":"+call(p,"getIntrinsicRatio")+",\"checks\":["+String.join(",",vals)+"]}";}
 static String stem(Object s)throws Exception {if(s==null)return "null";Line2D m=(Line2D)call(s,"getMedian");return "{\"grade\":"+call(s,"getGrade")+",\"bounds\":"+rect(call(s,"getBounds"))+",\"median\":["+m.getX1()+","+m.getY1()+","+m.getX2()+","+m.getY2()+"],\"width\":"+call(s,"getWidth")+",\"glyph\":"+physical(call(s,"getGlyph"))+",\"impacts\":"+impacts(call(s,"getImpacts"))+",\"in_sig\":"+(call(s,"getSig")!=null)+",\"id\":"+call(s,"getId")+"}";}
 public void process(){try{
  Object sheet=call(((List<?>)call(book,"getStubs")).get(0),"getSheet"),sys=((List<?>)call(sheet,"getSystems")).get(0),sig=call(sys,"getSig");
  Object retr=Class.forName("org.audiveris.omr.sheet.stem.StemsRetriever").getConstructor(Class.forName("org.audiveris.omr.sheet.SystemInfo")).newInstance(sys);call(retr,"process");
  Object builder=null;for(Object head:(List<?>)get(retr,"systemHeads")){Object linker=call(head,"getLinker");if(linker==null)continue;for(String side:new String[]{"LEFT","RIGHT"})for(String vert:new String[]{"TOP","BOTTOM"}){Object corner=call(linker,"getCornerLinker",en("util.HorizontalSide",side),en("util.VerticalSide",vert));Object sb=get(corner,"sb");if(sb!=null){builder=sb;break;}}if(builder!=null)break;}if(builder==null)throw new IllegalStateException("no legitimately initialized original CLinker StemBuilder");
  Object checker=call(retr,"getStemChecker"),saved=get(checker,"pixelFilter"),index=call(sheet,"getGlyphIndex"),scale=call(sheet,"getScale");List<String> cases=new ArrayList<>();int c=0;
  try{for(int h:new int[]{31,40,64})for(String orientation:new String[]{"VERTICAL","HORIZONTAL"})for(int count:new int[]{1,2}){
   int x=40+c++*5,y=40;List<Object> parts=new ArrayList<>();if(count==1)parts.add(glyph(x,y,2,h,orientation));else{parts.add(glyph(x,y,2,h/2,orientation));parts.add(glyph(x,y+h/2,2,h-h/2,orientation));}
   List<String> ps=new ArrayList<>();for(Object g:parts)ps.add(physical(g));byte[] pixels=new byte[896*160];Arrays.fill(pixels,(byte)255);for(int yy=y;yy<y+h;yy++)for(int xx=x;xx<x+2;xx++)pixels[yy*896+xx]=0;Object bp=Class.forName("ij.process.ByteProcessor").getConstructor(int.class,int.class,byte[].class).newInstance(896,160,pixels);set(checker,"pixelFilter",bp);
   Object first=call(builder,"createStem",parts,0);if(first==null)throw new IllegalStateException("expected accepted stem");String before=stem(first);int vertices=((Collection<?>)call(sig,"vertexSet")).size();call(sig,"addVertex",first);String registered=stem(first);Arrays.fill(pixels,(byte)255);Object cached=call(builder,"createStem",parts,1);String afterCache=stem(cached);int added=((Collection<?>)call(sig,"vertexSet")).size()-vertices;call(first,"remove");Object afterRemoval=call(builder,"createStem",parts,0);
   cases.add("{\"parts\":["+String.join(",",ps)+"],\"before_SIG\":"+before+",\"after_SIG\":"+registered+",\"after_cached_white\":"+afterCache+",\"cached_same_object_after_SIG\":"+(first==cached)+",\"vertices_added\":"+added+",\"removed\":"+call(first,"isRemoved")+",\"cached_same_object_after_removal\":"+(first==afterRemoval)+",\"after_removed\":"+stem(afterRemoval)+",\"cached_removed_flag\":"+call(afterRemoval,"isRemoved")+",\"vertices_after_removal_delta\":"+(((Collection<?>)call(sig,"vertexSet")).size()-vertices)+"}");
  }}finally{set(checker,"pixelFilter",saved);}
  Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"native_outputs_used\":false,\"scope\":\"Original selected cache-to-SIG lifecycle and retained removed cache identity; no automatic STEMS claim\",\"cases\":["+String.join(",",cases)+"]}");
 }catch(Exception e){throw new RuntimeException(e);}}
}
